// Build canonical WF-60 input payload for Slack-inbound logging.
// Fired as a side-branch from Extract Required Fields — MUST NOT block routing.
const input = $input.first().json;

return [{
  json: {
    transport: 'slack',
    direction: 'inbound',
    messageType: 'slack_text',
    content: input.message_text || null,
    slackChannelId: input.channel_id || null,
    slackMessageTs: input.timestamp || null,
    userId: null,            // WF-60 resolves via slack_channel_id → users.id lookup
    consultationId: null,
    whatsappMessageId: null,
    phoneNumber: null,
    metadata: {
      transport: 'slack',
      slackChannelId: input.channel_id || null,
      slackUserId: input.user_id || null,
      slackMessageTs: input.timestamp || null,
      channelName: input.channel_name || null,
      timestamp: new Date().toISOString()
    }
  }
}];

// WF-10 Step 10 — Classify Admin Channel Message (SP-03 + BUG-02 systemic fix)
// Added commandType (LIST | STATS | HELP) for admin_wide. Strips Slack mrkdwn.
const input = $input.first().json;

function stripSlackMrkdwn(s) {
  return (s || '')
    .replace(/<tel:[^|>]*\|([^>]+)>/gi, '$1')
    .replace(/<(?:https?:[^|>]*\|)?([^>]+)>/gi, '$1')
    .replace(/^[`*_~]+|[`*_~]+$/g, '')
    .trim();
}

const messageText = stripSlackMrkdwn(input.message_text);
const messageUpper = messageText.toUpperCase();

const adminWide = ['LIST', 'STATS', 'HELP'];
const userTargeted = ['APPROVE', 'REJECT', 'CLOSE', 'BLOCK', 'UNBLOCK'];

const matchedAdminWide = adminWide.find(k => messageUpper.startsWith(k));
const matchedUserTargeted = userTargeted.find(k => messageUpper.startsWith(k));

let kind;
let commandType = null;
let commandHint = null;
if (matchedAdminWide) {
  kind = 'admin_wide_cmd';
  commandHint = matchedAdminWide;
  commandType = matchedAdminWide;
} else if (matchedUserTargeted) {
  kind = 'user_targeted_cmd';
  commandHint = matchedUserTargeted;
} else {
  kind = 'free_text';
}

return [{
  json: {
    messageText: messageText,
    adminUserId: input.user_id,
    channelId: input.channel_id,
    channelName: input.name_normalized,
    kind: kind,
    commandHint: commandHint,
    commandType: commandType
  }
}];

// WF-10 Step 15 — Classify User Channel Message (SP-03 + BUG-02 systemic fix)
// Strips Slack mrkdwn (<tel:+xxx|yyy> → yyy, <http..|label> → label) before classification.
// Renamed commandKeyword → commandType. Added reason extraction (tokens after typedPhone).
const input = $input.first().json;

function stripSlackMrkdwn(s) {
  return (s || '')
    .replace(/<tel:[^|>]*\|([^>]+)>/gi, '$1')
    .replace(/<(?:https?:[^|>]*\|)?([^>]+)>/gi, '$1')
    .replace(/^[`*_~]+|[`*_~]+$/g, '')
    .trim();
}

const messageText = stripSlackMrkdwn(input.message_text);
const messageUpper = messageText.toUpperCase();
const channelName = input.name_normalized || '';

const adminWide = ['LIST', 'STATS', 'HELP'];
const userTargetedAliases = {
  'APPROVE PAYMENT': 'APPROVE_PAYMENT',
  'APPROVE': 'APPROVE_PAYMENT',
  'REJECT PAYMENT': 'REJECT_PAYMENT',
  'REJECT': 'REJECT_PAYMENT',
  'CLOSE CHAT CONSULT': 'CLOSE_CONSULTATION',
  'CLOSE CONSULTATION': 'CLOSE_CONSULTATION',
  'CLOSE CONSULT': 'CLOSE_CONSULTATION',
  'CLOSE': 'CLOSE_CONSULTATION',
  'BLOCK': 'BLOCK_USER',
  'UNBLOCK': 'UNBLOCK_USER'
};
const aliasKeys = Object.keys(userTargetedAliases).sort((a, b) => b.length - a.length);

let kind;
let commandType = null;
let commandHint = null;
if (adminWide.some(k => messageUpper.startsWith(k))) {
  kind = 'admin_wide_cmd';
  commandHint = adminWide.find(k => messageUpper.startsWith(k));
} else {
  const matched = aliasKeys.find(a => messageUpper === a || messageUpper.startsWith(a + ' '));
  if (matched) {
    kind = 'user_targeted_cmd';
    commandType = userTargetedAliases[matched];
    commandHint = matched;
  } else {
    kind = 'relay_text';
  }
}

let channelDerivedPhone = null;
const cm = channelName.match(/^consult-(\+?\d{10,15})$/i);
if (cm) channelDerivedPhone = cm[1].replace(/^\+/, '');

let typedPhone = null;
let reason = '';
if (commandType) {
  const matched = aliasKeys.find(a => messageUpper === a || messageUpper.startsWith(a + ' '));
  const remainder = matched ? messageText.substring(matched.length).trim() : messageText;
  const pm = remainder.match(/(\+?\d{10,15})/);
  if (pm) {
    typedPhone = pm[1].replace(/^\+/, '');
    const idx = remainder.indexOf(pm[1]);
    reason = remainder.substring(idx + pm[1].length).trim();
  }
}

let phoneStatus;
if (kind === 'user_targeted_cmd') {
  if (!typedPhone) phoneStatus = 'absent';
  else if (typedPhone !== channelDerivedPhone) phoneStatus = 'mismatch';
  else phoneStatus = 'ok';
} else {
  phoneStatus = 'bypass';
}

const expectedStateMap = {
  'APPROVE_PAYMENT': 'payment_submitted',
  'REJECT_PAYMENT': 'payment_submitted',
  'CLOSE_CONSULTATION': 'consultation_active',
  'BLOCK_USER': '*',
  'UNBLOCK_USER': 'blocked'
};
let expectedState;
if (kind === 'relay_text') expectedState = 'consultation_active';
else if (kind === 'user_targeted_cmd') expectedState = expectedStateMap[commandType] || '*';
else expectedState = '*';

return [{
  json: {
    messageText: messageText,
    messageUpper: messageUpper,
    adminUserId: input.user_id,
    channelId: input.channel_id,
    channelName: channelName,
    kind: kind,
    commandType: commandType,
    commandHint: commandHint,
    typedPhone: typedPhone,
    channelDerivedPhone: channelDerivedPhone,
    phoneStatus: phoneStatus,
    expectedState: expectedState,
    reason: reason
  }
}];

// Build WF-10 Command Envelope — §2.2 data-contract-discipline Phase 1.
// Receives output from either Build WF-11 Payload (user-targeted) or
// Build WF-11 Payload (Admin) (admin-wide). Merges the pre-shaped payload
// with the user row (if available) to emit the canonical WF-11 contract.
// For admin-wide commands (LIST/STATS/HELP) no user row exists — user is null.

const inp = $input.first().json;

let userRow = null;
try {
  const row = $('Load User Status').item.json;
  if (row && row.id) {
    userRow = {
      id: row.id,
      name: row.name,
      phone_number: row.phone_number,
      status: row.status,
      slack_channel_id: row.slack_channel_id
    };
  }
} catch (_) {
  userRow = null;
}

return [{
  json: {
    commandType: inp.commandType,
    phoneNumber: inp.phoneNumber || null,
    reason: inp.reason || '',
    adminUserId: inp.adminUserId,
    channelId: inp.channelId,
    channelName: inp.channelName,
    messageText: inp.messageText,
    user: userRow
  }
}];

// Build WF-10 Relay Envelope — §2.2 data-contract-discipline Phase 1.
// Receives output from Build WF-41 Payload (relay_text path, post state-match).
// Augments with full user context from Load User Status for WF-41 consumption.
// NOTE: current_consultation_id is not loaded by the existing Load User Status
// SELECT (id, status, name, phone_number); it is included as null here and
// flagged as adjacent finding — Phase 2 SELECT expansion needed.

const inp = $input.first().json;

const row = $('Load User Status').item.json;
const userObj = {
  id: row.id || null,
  name: row.name || null,
  phone_number: row.phone_number || null,
  status: row.status || null,
  slack_channel_id: row.slack_channel_id || null,
  current_consultation_id: row.current_consultation_id || null
};

return [{
  json: {
    phoneNumber: inp.phoneNumber,
    messageText: inp.messageText,
    user: userObj,
    adminUserId: $('Classify User Channel Message').item.json.adminUserId,
    channelId: $('Classify User Channel Message').item.json.channelId,
    channelName: $('Classify User Channel Message').item.json.channelName
  }
}];

const resp = $input.first().json;
const channelId = $('Extract Required Fields').first().json.channel_id;
const cands = resp.candidates || [];
const parts = (((cands[0] || {}).content) || {}).parts || [];
const answer = ((parts[0] || {}).text || '').toString().trim();
const geminiOk = answer.length > 0;
return [{ json: { channelId, geminiOk, answer } }];

